'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { User, Mail, Phone, ArrowLeft } from 'lucide-react';
import Image from 'next/image';

export default function ProfilePage() {
    const router = useRouter();

    const [profileData, setProfileData] = useState({
        name: '',
        email: '',
        gender: '',
        phone: ''
    });

    useEffect(() => {
        // Load profile data from local storage
        const storedName = localStorage.getItem('disc_user_name') || 'Not provided';
        const storedPhone = localStorage.getItem('disc_user_phone') || 'Not provided';

        setProfileData({
            name: storedName,
            phone: storedPhone,
            email: 'Not provided', // Email not currently stored
            gender: 'Not provided' // Gender not currently stored
        });
    }, []);

    return (
        <main className="min-h-screen flex flex-col items-center justify-center p-4 bg-black relative">
            {/* Logo - Top Left */}
            <div className="absolute top-8 left-8 z-20">
                <Image
                    src="/logo.png"
                    alt="Inqisity Logo"
                    width={180}
                    height={54}
                    className="object-contain"
                />
            </div>

            {/* Background Ambience */}
            <div className="fixed inset-0 z-0 pointer-events-none">
                <div className="absolute top-0 w-full h-full bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-zinc-900/50 via-black to-black" />
            </div>

            <div className="z-10 w-full max-w-2xl">
                <button
                    onClick={() => router.back()}
                    className="mb-8 flex items-center gap-2 text-zinc-400 hover:text-white transition-colors"
                >
                    <ArrowLeft size={20} />
                    <span>Back to Dashboard</span>
                </button>

                <div className="glass-panel p-8 md:p-12 rounded-3xl border border-white/10 bg-zinc-900/60">
                    <h1 className="text-3xl font-light text-white mb-8 border-b border-white/10 pb-4">
                        My Profile
                    </h1>

                    <div className="space-y-6">
                        {/* Phone */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Mobile Number</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">
                                    <Phone size={18} />
                                </span>
                                <div className="w-full bg-black/30 border border-white/5 rounded-xl px-12 py-3 text-zinc-300">
                                    {profileData.phone}
                                </div>
                            </div>
                        </div>

                        {/* Name */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Full Name</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">
                                    <User size={18} />
                                </span>
                                <div className="w-full bg-black/30 border border-white/5 rounded-xl px-12 py-3 text-zinc-300">
                                    {profileData.name}
                                </div>
                            </div>
                        </div>

                        {/* Email */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Email Address</label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-500">
                                    <Mail size={18} />
                                </span>
                                <div className="w-full bg-black/30 border border-white/5 rounded-xl px-12 py-3 text-zinc-300">
                                    {profileData.email}
                                </div>
                            </div>
                        </div>

                        {/* Gender */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-zinc-400 ml-1">Gender</label>
                            <div className="w-full bg-black/30 border border-white/5 rounded-xl px-4 py-3 text-zinc-300">
                                {profileData.gender}
                            </div>
                        </div>
                    </div>

                    {/* Info Message */}
                    <div className="mt-8 p-4 bg-cyan-500/10 border border-cyan-500/20 rounded-xl">
                        <p className="text-sm text-cyan-300 text-center">
                            This is a view-only profile. Contact support to update your information.
                        </p>
                    </div>
                </div>
            </div>
        </main>
    );
}
